USE rezantech;
CREATE TABLE IF NOT EXISTS bookmarks (user_id BIGINT UNSIGNED NOT NULL,post_slug VARCHAR(180) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,post_slug),CONSTRAINT fk_bookmark_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS claps (user_id BIGINT UNSIGNED NOT NULL,post_slug VARCHAR(180) NOT NULL,count TINYINT UNSIGNED NOT NULL DEFAULT 1,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(user_id,post_slug),CONSTRAINT fk_clap_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS topic_follows (user_id BIGINT UNSIGNED NOT NULL,category_id INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,category_id),CONSTRAINT fk_topic_follow_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_topic_follow_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS user_follows (follower_id BIGINT UNSIGNED NOT NULL,followed_id BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(follower_id,followed_id),CONSTRAINT fk_follower FOREIGN KEY(follower_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_followed FOREIGN KEY(followed_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,type VARCHAR(30) NOT NULL,message VARCHAR(255) NOT NULL,link VARCHAR(255) NOT NULL DEFAULT '',read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_user_notice(user_id,read_at,created_at),CONSTRAINT fk_notice_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
